import {analyzeAudio,createDemoBuffer,synthesize,recommend,encodeWav} from './audio-engine.js';
const $=id=>document.getElementById(id);
const key='still-comfort-v1';
let ctx,features,candidates=[],selected,generated,sourceNode,gainNode,session,recorder,recordStream,recordTimer,recordTick,analyzing=false,playToken=0;
let history=[];
try{const stored=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(stored))history=stored.filter(x=>x&&typeof x.kind==='string'&&[-1,0,1].includes(x.comfort)&&typeof x.at==='string').slice(-200);}catch{}
function say(message){$('status').textContent=message;}
function getContext(){if(!ctx)ctx=new (window.AudioContext||window.webkitAudioContext)();return ctx;}
function currentContext(){return {mood:$('mood').value,environment:$('environment').value,sensitivity:Number($('sensitivity').value)};}
function pain(id){return $(id).value===''?null:Number($(id).value);}
function readDuration(file){return new Promise((resolve,reject)=>{const media=document.createElement('audio'),url=URL.createObjectURL(file);const cleanup=()=>{clearTimeout(timer);media.onloadedmetadata=null;media.onerror=null;media.removeAttribute('src');media.load();URL.revokeObjectURL(url);};const timer=setTimeout(()=>{cleanup();reject(new Error('Could not read this clip’s duration. Try a short WAV or MP3 file.'));},10000);media.preload='metadata';media.onloadedmetadata=()=>{const duration=media.duration;cleanup();Number.isFinite(duration)&&duration>0?resolve(duration):reject(new Error('Could not read this clip’s duration. Try a short WAV or MP3 file.'));};media.onerror=()=>{cleanup();reject(new Error('This audio format is not supported here. Try WAV or MP3.'));};media.src=url;});}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function setBusy(value){analyzing=value;$('demo').disabled=value;$('audio-file').disabled=value;$('record').disabled=value;}
function finishSession(){if(session?.startedAt&&!session.endedAt){session.endedAt=Date.now();session.volumeStop=Number($('volume').value);session.listenedSeconds=Math.min(30,(session.endedAt-session.startedAt)/1000);}}
function stopAudio(message){playToken++;if(sourceNode){try{sourceNode.stop();}catch{}sourceNode.disconnect();sourceNode=null;}if(gainNode){gainNode.disconnect();gainNode=null;}finishSession();$('stop').disabled=true;$('play').disabled=!generated;$('play').textContent='▶ Play 30 seconds';if(message)say(message);}
function resetFeedback(){session=null;$('save').disabled=true;$('pain-after').value='';document.querySelectorAll('[name=comfort]').forEach(x=>x.checked=false);$('notes').value='';}
function drawSpectrogram(f){const canvas=$('spectrogram'),g=canvas.getContext('2d'),w=canvas.width,h=canvas.height;g.fillStyle='#1d342a';g.fillRect(0,0,w,h);const frames=f.spectrogram.frames;for(let x=0;x<frames.length;x++){for(let y=0;y<frames[x].length;y++){const v=frames[x][y];g.fillStyle=`rgb(${Math.round(26+v*167)},${Math.round(49+v*157)},${Math.round(39+v*101)})`;g.fillRect(x*w/frames.length,h-(y+1)*h/frames[x].length,Math.ceil(w/frames.length),Math.ceil(h/frames[x].length));}}canvas.setAttribute('aria-label',`Spectrogram of the first ${f.analyzedSeconds.toFixed(1)} seconds, ${f.spectrogram.minHz} to ${Math.round(f.spectrogram.maxHz)} Hz. Brighter areas show more relative spectral energy.`);$('plot-empty').hidden=true;$('plot-empty').style.display='none';$('plot-duration').textContent=f.analyzedSeconds.toFixed(1)+' seconds';}
function renderFeatures(f,name,source){$('source-name').textContent=name;$('source-tag').textContent=source;$('brightness').textContent=f.silent?'Silent':f.centroidHz<600?'Dark':f.centroidHz<2000?'Balanced':'Bright';$('centroid').textContent=Math.round(f.centroidHz)+' Hz centroid';$('peak').textContent=f.silent?'—':Math.round(f.dominantHz)+' Hz';$('texture').textContent=f.silent?'Silent':f.flatness<.08?'Tonal':'Noise-like';$('texture-detail').textContent='Flatness '+f.flatness.toFixed(3);$('channel-label').textContent=`${f.channels} channel${f.channels===1?'':'s'} · ${(f.sampleRate/1000).toFixed(1)} kHz`;for(const band of ['low','mid','high']){$('band-'+band).style.width=(f.bandEnergy[band]*100)+'%';$(band+'-label').textContent='● '+band[0].toUpperCase()+band.slice(1)+' '+Math.round(f.bandEnergy[band]*100)+'%';}const peaks=f.stereo.channelPeaksHz.map(v=>Math.round(v)+' Hz').join(' / ');$('analysis-details').textContent=`First ${f.analyzedSeconds.toFixed(1)} of ${f.duration.toFixed(1)} seconds; 4,096-sample Hann windows, up to 120 sampled frames. Channels’ power is averaged, not their waveforms. Channel peaks: ${peaks}. Bands: low 30–250 Hz, mid 250–2,000 Hz, high 2,000 Hz to Nyquist. Plot: 50 Hz–${Math.round(f.spectrogram.maxHz).toLocaleString()} Hz, logarithmic frequency, relative energy. These are digital measurements, not calibrated headphone loudness.`;drawSpectrogram(f);}
function preferenceFor(kind){const c=currentContext();const matches=history.filter(x=>x.kind===kind&&x.context?.mood===c.mood&&x.context?.environment===c.environment);return {count:matches.length,average:matches.length?matches.reduce((a,x)=>a+x.comfort,0)/matches.length:0};}
function refreshCandidates(keepSelection=false){if(!features)return;candidates=recommend(features).map(c=>{const p=preferenceFor(c.kind);return {...c,brightness:c.brightness*(Number($('sensitivity').value)===2?.45:1),personal:p,order:c.score+p.average*.65};}).sort((a,b)=>b.order-a.order);renderCandidates();if(!candidates.length){selected=null;generated=null;$('play').disabled=true;$('download').disabled=true;$('frequency').disabled=true;$('beat').disabled=true;$('track-name').textContent='No audible signal';$('track-description').textContent='Try a different clip or recording.';return;}if(!keepSelection||!selected)selectCandidate(candidates[0].id);else renderCandidates();}
function renderCandidates(){const container=$('recommendations');container.replaceChildren();if(!candidates.length){const empty=document.createElement('div');empty.className='empty-card';empty.textContent='No audible signal found. Try another clip.';container.append(empty);return;}candidates.forEach((c,i)=>{const card=document.createElement('button');card.className='sound-card'+(selected?.id===c.id?' selected':'');card.setAttribute('aria-pressed',String(selected?.id===c.id));const top=document.createElement('span');top.className='card-top';top.textContent=`0${i+1} / ${c.kind==='binaural'?'EXPLORE STEREO':c.personal.count?'PERSONAL FEEDBACK':'ACOUSTIC STARTING POINT'}`;const title=document.createElement('strong');title.textContent=c.name;const reason=document.createElement('p');reason.textContent=c.reason;const foot=document.createElement('span');foot.className='card-foot';foot.textContent=c.personal.count?`${c.personal.count} check-in${c.personal.count===1?'':'s'} in this context · ${selected?.id===c.id?'Selected':'Select →'}`:`30-second sketch · ${selected?.id===c.id?'Selected':'Select →'}`;card.append(top,title,reason,foot);card.addEventListener('click',()=>selectCandidate(c.id));container.append(card);});}
function updateLabels(){$('frequency-value').textContent=$('frequency').value+' Hz';$('beat-value').textContent=selected?.kind==='binaural'?$('beat').value+' Hz':'Off';$('volume-value').textContent=$('volume').value+'%';$('sensitivity-value').textContent=['Low','Medium','High'][Number($('sensitivity').value)];}
function renderTrack(){if(!selected)return;$('track-name').textContent=selected.name;$('track-description').textContent=selected.kind==='binaural'?`${selected.frequency} Hz left · ${selected.frequency+selected.beatHz} Hz right · ${selected.beatHz===0?'same-tone comparison':selected.beatHz+' Hz difference'}`:selected.kind==='rain'?'Filtered noise · soft, slowly varying texture':`${selected.frequency} Hz base tone · gentle harmonics`;$('player-note').textContent=selected.kind==='binaural'?'Stereo headphones are needed for the binaural effect. Set the difference to 0 Hz for a same-tone comparison. The displayed difference is not an established migraine treatment.':'Original procedural synthesis, not AI music generation. No music catalog or Shazam service is connected.';}
function regenerate(){if(!selected)return;stopAudio();resetFeedback();generated=synthesize(getContext(),{...selected,seconds:30,seed:41});$('play').disabled=false;$('download').disabled=false;renderTrack();}
function selectCandidate(id){stopAudio();selected={...candidates.find(c=>c.id===id)};$('frequency').value=selected.frequency;$('beat').value=selected.kind==='binaural'?selected.beatHz:0;$('frequency').disabled=selected.kind==='rain';$('beat').disabled=selected.kind!=='binaural';regenerate();updateLabels();renderCandidates();}
async function analyzeBuffer(buffer,name,source){stopAudio();resetFeedback();setBusy(true);say('Measuring the sound…');await new Promise(r=>setTimeout(r,30));try{features=analyzeAudio(buffer);renderFeatures(features,name,source);refreshCandidates();say(features.silent?'This clip is silent or too quiet to analyze. Try another sound.':'Your sound is ready. Select a sketch and press Play when you feel comfortable.');}catch(e){say('Could not analyze this clip: '+e.message);}finally{setBusy(false);}}
$('demo').addEventListener('click',()=>analyzeBuffer(createDemoBuffer(getContext()),'Original demo · soft harmonic tone','DEMO'));
$('audio-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file)return;if(file.size>20*1024*1024){say('Please choose a clip smaller than 20 MB.');event.target.value='';return;}stopAudio();setBusy(true);say('Opening your audio locally…');try{const duration=await readDuration(file);if(duration>120)throw new Error('Please trim this file to 2 minutes or less. Only the first 30 seconds are analyzed.');const buffer=await getContext().decodeAudioData(await file.arrayBuffer());await analyzeBuffer(buffer,file.name,'YOUR FILE');}catch(e){say(e.message||'This file could not be decoded. Try a short WAV or MP3 audio file.');}finally{setBusy(false);event.target.value='';}});
function endRecording(){if(recorder?.state==='recording')setBusy(true);clearTimeout(recordTimer);clearInterval(recordTick);if(recorder?.state==='recording')recorder.stop();recordStream?.getTracks().forEach(t=>t.stop());$('record').textContent='◉ Record 10 seconds';}
$('record').addEventListener('click',async()=>{if(recorder?.state==='recording'){endRecording();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){say('Microphone recording is unavailable here. Use an audio file or the demo.');return;}stopAudio();setBusy(true);try{recordStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});const chunks=[];recorder=new MediaRecorder(recordStream);const recording=recorder;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=async()=>{setBusy(true);recordStream?.getTracks().forEach(t=>t.stop());clearTimeout(recordTimer);clearInterval(recordTick);$('record').textContent='◉ Record 10 seconds';try{const buffer=await getContext().decodeAudioData(await new Blob(chunks,{type:recording.mimeType}).arrayBuffer());await analyzeBuffer(buffer,'Microphone · '+buffer.duration.toFixed(1)+' seconds','RECORDING');}catch{say('No usable audio was captured. Try a file or record a little longer.');setBusy(false);}};recorder.start();let seconds=10;$('record').disabled=false;$('record').textContent='■ Stop recording · 10s';$('demo').disabled=true;$('audio-file').disabled=true;recordTick=setInterval(()=>{$('record').textContent='■ Stop recording · '+Math.max(0,--seconds)+'s';},1000);recordTimer=setTimeout(endRecording,10000);say('Recording locally for up to 10 seconds. Hum or play your reference nearby.');}catch(e){recordStream?.getTracks().forEach(t=>t.stop());say('Microphone access was not available. You can still choose a file or try the demo.');setBusy(false);}});
$('play').addEventListener('click',async()=>{if(!generated)return;stopAudio();resetFeedback();const token=++playToken;try{const audio=getContext();await audio.resume();if(token!==playToken)return;const node=audio.createBufferSource(),gain=audio.createGain();node.buffer=generated;gain.gain.value=Number($('volume').value)/100;node.connect(gain);gain.connect(audio.destination);sourceNode=node;gainNode=gain;session={at:new Date().toISOString(),startedAt:Date.now(),kind:selected.kind,name:selected.name,settings:{frequency:selected.frequency,beatHz:selected.beatHz,brightness:selected.brightness,seconds:30,seed:41},volumeStart:Number($('volume').value),hadNonzeroAppGain:Number($('volume').value)>0,context:currentContext(),painBefore:pain('pain-before'),reference:{centroidHz:features.centroidHz,dominantHz:features.dominantHz,flatness:features.flatness}};node.onended=()=>{if(sourceNode!==node)return;stopAudio('Sketch finished. You can save how it felt.');};node.start();$('play').disabled=true;$('play').textContent='Playing…';$('stop').disabled=false;$('save').disabled=false;say('Playing quietly. Stop whenever you want; there is no need to finish the clip.');}catch(e){stopAudio();say('Audio playback is unavailable in this browser: '+e.message);}});
$('stop').addEventListener('click',()=>stopAudio('Stopped. Quiet is a valid choice.'));
$('uncomfortable').addEventListener('click',()=>{stopAudio('Stopped. Take a break from sound if that feels better.');document.querySelector('[name=comfort][value="-1"]').checked=true;});
for(const id of ['frequency','beat'])$(id).addEventListener('input',()=>{if(!selected)return;selected.frequency=Number($('frequency').value);selected.beatHz=selected.kind==='binaural'?Number($('beat').value):0;updateLabels();regenerate();say('Sound updated. Press Play to try it.');});
$('volume').addEventListener('input',()=>{updateLabels();if(session&&!session.endedAt&&sourceNode&&Number($('volume').value)>0)session.hadNonzeroAppGain=true;if(gainNode)gainNode.gain.setTargetAtTime(Number($('volume').value)/100,ctx.currentTime,.05);});
for(const id of ['mood','environment','sensitivity'])$(id).addEventListener('change',()=>{updateLabels();if(features){refreshCandidates();say('Suggestions updated for this moment.');}});
$('download').addEventListener('click',()=>{if(generated){const exportBuffer=getContext().createBuffer(generated.numberOfChannels,generated.length,generated.sampleRate),level=Number($('volume').value)/100;for(let c=0;c<generated.numberOfChannels;c++){const input=generated.getChannelData(c),output=exportBuffer.getChannelData(c);for(let i=0;i<input.length;i++)output[i]=input[i]*level;}downloadBlob(encodeWav(exportBuffer),'still-'+selected.kind+'-'+selected.frequency+'hz-'+selected.beatHz+'beat.wav');say('WAV downloaded at the current preview volume. Playback device settings still affect listening level.');}});
$('feedback').addEventListener('submit',event=>{event.preventDefault();if(!session){say('Play a sketch before saving a check-in.');return;}const comfort=document.querySelector('[name=comfort]:checked');if(!comfort){say('Choose how the sound felt before saving.');return;}stopAudio();const entry={...session,comfort:Number(comfort.value),painAfter:pain('pain-after'),notes:$('notes').value.trim(),volumeEnd:session.volumeStop};history=[...history,entry].slice(-200);let persisted=true;try{localStorage.setItem(key,JSON.stringify(history));}catch{persisted=false;}resetFeedback();renderHistory();refreshCandidates(true);say(persisted?'Check-in saved on this device. Your feedback now helps order suggestions in this context.':'Check-in kept for this visit only; browser storage is unavailable. Export it to keep a copy.');});
function renderHistory(){$('history-title').textContent=history.length?`${history.length} check-in${history.length===1?'':'s'} saved`:'No check-ins yet';$('export').disabled=!history.length;$('clear').disabled=!history.length;const list=$('history');list.replaceChildren();if(!history.length){const p=document.createElement('p');p.className='muted';p.textContent='Your observations will appear here.';list.append(p);return;}history.slice(-6).reverse().forEach(entry=>{const row=document.createElement('div');row.className='history-row';const date=document.createElement('span');date.textContent=new Date(entry.at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});const name=document.createElement('strong');name.textContent=entry.name;const feeling=document.createElement('span');feeling.textContent=['Uncomfortable','Neutral','Comforting'][entry.comfort+1]+' · '+(entry.listenedSeconds||0).toFixed(0)+'s';const change=document.createElement('span');change.textContent=entry.painBefore!==null&&entry.painAfter!==null?`Pain ${entry.painBefore} → ${entry.painAfter} / 10`:'Pain not fully recorded';row.append(date,name,feeling,change);list.append(row);});}
$('export').addEventListener('click',()=>downloadBlob(new Blob([JSON.stringify({schema:'still-comfort-v1',exportedAt:new Date().toISOString(),purpose:'Personal comfort observations; not evidence of treatment efficacy',sessions:history},null,2)],{type:'application/json'}),'still-check-ins.json'));
$('clear').addEventListener('click',()=>{history=[];try{localStorage.removeItem(key);}catch{}renderHistory();refreshCandidates(true);say('Saved check-ins cleared from this browser. Downloaded exports are separate files.');});
$('dim').addEventListener('click',()=>{const on=document.body.classList.toggle('dim');$('dim').textContent=on?'Light screen':'Dim screen';$('dim').setAttribute('aria-pressed',String(on));});
for(const id of ['pain-before','pain-after'])for(let i=0;i<=10;i++){const option=document.createElement('option');option.value=i;option.textContent=i+(i===0?' · no pain':i===10?' · worst pain':'');$(id).append(option);}
window.addEventListener('pagehide',()=>{stopAudio();endRecording();});
renderHistory();updateLabels();
